<h1 class="h3 mb-3">Carrinho de vendas</h1><div class="row g-4"><section class="col-lg-7"><div class="card card-body mb-3"><form class="d-flex gap-2" method="get"><input type="hidden" name="route" value="cart"><input class="form-control" name="q" placeholder="Buscar produto por nome ou código" value="<?= htmlspecialchars($_GET['q']??'') ?>"><button class="btn btn-outline-primary">Buscar</button></form></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Produto</th><th>Estoque</th><th>Preço</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= htmlspecialchars($p['nome']) ?></td><td><?= (int)$p['quantidade'] ?></td><td>R$ <?= number_format((float)$p['preco_unitario'],2,',','.') ?></td><td><form class="d-flex gap-1" method="post" action="index.php?route=cart-add"><input type="hidden" name="produto_id" value="<?= (int)$p['id'] ?>"><input class="form-control form-control-sm" style="width:75px" type="number" name="quantidade" min="1" max="<?= (int)$p['quantidade'] ?>" value="1"><button class="btn btn-sm btn-success">Adicionar</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section><section class="col-lg-5"><div class="card card-body"><h2 class="h5">Itens selecionados</h2><?php if(!$cartRows): ?><p class="text-muted">Seu carrinho está vazio.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($cartRows as $r): ?><tr><td><?= htmlspecialchars($r['nome']) ?></td><td><form method="post" action="index.php?route=cart-update" class="d-flex gap-1"><input type="hidden" name="produto_id" value="<?= (int)$r['id'] ?>"><input class="form-control form-control-sm" style="width:65px" type="number" min="0" name="quantidade" value="<?= (int)$r['cart_qty'] ?>"><button class="btn btn-sm btn-outline-secondary">OK</button></form></td><td>R$ <?= number_format($r['subtotal'],2,',','.') ?></td><td><form method="post" action="index.php?route=cart-remove"><input type="hidden" name="produto_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger">×</button></form></td></tr><?php endforeach; ?></tbody></table></div><hr><div class="d-flex justify-content-between fs-5"><strong>Total</strong><strong>R$ <?= number_format($total,2,',','.') ?></strong></div><form method="post" action="index.php?route=checkout" class="mt-3"><label class="form-label">Cliente (opcional)</label><select class="form-select mb-3" name="cliente_id"><option value="">Consumidor não identificado</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= htmlspecialchars($c['nome']) ?></option><?php endforeach; ?></select><button class="btn btn-primary w-100" onclick="return confirm('Confirmar a venda?')">Finalizar venda</button></form><?php endif; ?></div></section></div>
